EOF_V19
base64 -d "$PKG/visgrid-v19.lua.b64" > "$PKG/visgrid-v19.lua"
rm -f "$PKG/visgrid-v19.lua.b64"
test "$(sha256sum "$PKG/visgrid-v19.lua" | awk '{print $1}')" = "$V19_SHA"
grep -Fq 'TSP_VISGRID_LUA_V19_RAY_PORTAL_AUTHORITY' "$PKG/visgrid-v19.lua"
grep -Fq 'TSP_VISGRID_V19_LOADSAFE_6S' "$PKG/visgrid-v19.lua"
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v19.lua"
echo "PASS: V19 SHA=$V19_SHA"

echo
echo "===== 3/6 BACK UP LIVE SENSOR FIRST ====="
ssh "${SSH[@]}" "$DEV" "
  set -e
  mkdir -p '$REMOTE_BACKUP'
  cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v19'
  cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v19'
  sha256sum '$BIN' '$LUA' '$TOPO' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
  sync
"
scp "${SSH[@]}" -q   "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v19"   "$PKG/device-backup/"
test "$(sha256sum "$PKG/device-backup/visgrid.lua.before-v19" | awk '{print $1}')" = "$LIVE_LUA"
echo "PASS: exact pre-V19 sensor backed up on device + Ubuntu."

echo
echo "===== 4/6 INSTALL LUA ONLY ====="
scp "${SSH[@]}" -q "$PKG/visgrid-v19.lua" "$DEV:/tmp/visgrid-v19.lua"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/visgrid-v19.lua" | awk '{print $1}')" = "$V19_SHA"

DEPLOY=1
ssh "${SSH[@]}" "$DEV" "
  set -e
  cp /tmp/visgrid-v19.lua '$LUA.new'
  mv -f '$LUA.new' '$LUA'
  rm -f /tmp/visgrid-v19.lua
  sync
"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')" = "$V19_SHA"
DEPLOY=0
echo "PASS: V19 sensor installed."

echo
echo "===== 5/6 VERIFY BINARY + TOPOLOGY UNCHANGED ====="
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')" = "$BIN_SHA"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')" = "$TOPO_SHA"
echo "PASS: proven PVS binary + topology are byte-identical."

echo
echo "===== 6/6 WRITE HELPERS DIRECTLY IN ~/Downloads ====="
cat > "$HOME/Downloads/pull-visgrid-v19-pvs.sh" <<'EOF_PULL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
  . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v19-pvs-trace-$STAMP.txt"
{
  echo "=================================================================="
  echo "VISGRID V19 RAY-AUTHORITY PVS TRACE"
  echo "=================================================================="
  echo "Ubuntu date: $(date)"
  ssh "${SSH[@]}" "$DEV" 'date; hostname'
  echo
  echo "===== V19 / PVS / VISGRID ====="
  ssh "${SSH[@]}" "$DEV" "
    grep -hE \
      'TSP_VISGRID_V19|TSP_VISGRID_V11|TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS|TSP_INTERIOR_VISGRID|TSP_LOAD_FREEZE|Lua.*ERROR|Lua.*error' \
      '$ROOT/openmw_051_log.txt' '$ROOT/config-0.51/openmw.log' \
      2>/dev/null | tail -5200 || true
  "
  echo
  echo "===== PERF ====="
  ssh "${SSH[@]}" "$DEV" "
    [ -f '$ROOT/openmw51_perf_latest.txt' ] &&
      tail -1000 '$ROOT/openmw51_perf_latest.txt' || true
  "
  echo
  echo "===== HASHES ====="
  ssh "${SSH[@]}" "$DEV" "
    sha256sum \
      '$ROOT/bin/openmw-0.51' \
      '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua' \
      '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua' \
      2>/dev/null || true
  "
} 2>&1 | tee "$OUT"
echo "Saved directly in Downloads:"
echo "  $OUT"

EOF_PULL
chmod +x "$HOME/Downloads/pull-visgrid-v19-pvs.sh"
bash -n "$HOME/Downloads/pull-visgrid-v19-pvs.sh"

cat > "$HOME/Downloads/rollback-visgrid-v19-pvs.sh" <<'EOF_ROLL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
  . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
if ssh "${SSH[@]}" "$DEV" \
  'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
  echo "ERROR: exit OpenMW normally before rollback."
  exit 20
fi
BACKUP="$(ssh "${SSH[@]}" "$DEV" \
  "ls -1dt '$ROOT'/backups/visgrid-v19-ray-authority-* 2>/dev/null | head -1")"
test -n "$BACKUP"
ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$BACKUP/visgrid.lua.before-v19'
  cp -p '$BACKUP/visgrid.lua.before-v19' \
    '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua'
  sync
  sha256sum \
    '$ROOT/bin/openmw-0.51' \
    '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua'
"
echo "PASS: exact pre-V19 sensor restored."
echo "V17 PVS binary was never changed."

EOF_ROLL
chmod +x "$HOME/Downloads/rollback-visgrid-v19-pvs.sh"
bash -n "$HOME/Downloads/rollback-visgrid-v19-pvs.sh"

cp -p "$HOME/Downloads/pull-visgrid-v19-pvs.sh" "$PKG/"
cp -p "$HOME/Downloads/rollback-visgrid-v19-pvs.sh" "$PKG/"

echo
echo "=================================================================="
echo "V19 RAY-AUTHORITY PVS INSTALLED"
echo "=================================================================="
echo "No rebuild."
echo "6-second load-safe hold preserved."
echo
echo "Key fixes:"
echo "  - ordinary VISGRID deep/miss rays now OPEN mapped destination PVS"
echo "  - proximity prefetch opens one adjacent room before threshold crossing"
echo "  - staying near a portal keeps both sides alive for turn-around safety"
echo "  - dedicated portal probe is secondary, not the gatekeeper"
echo "  - all nearby real door meshes get continuous depth protection"
echo "  - mapped self-loop/load-door directions get protection too"
echo "  - large_open minimum depth raised 2600 -> 3600"
echo
echo "Trace:"
echo "  ~/Downloads/pull-visgrid-v19-pvs.sh"
echo "Rollback:"
echo "  ~/Downloads/rollback-visgrid-v19-pvs.sh"
echo
echo "Telemetry:"
echo "  rp   = normal-ray portal evidence checks"
echo "  ro   = normal rays that opened a destination room"
echo "  prox = proximity prefetch openings"
echo "  dp   = door-protection refreshes"
echo "  pp/po remain the old dedicated probe counts"
echo "=================================================================="
